+        historyDropReport(historyDrops: 13, registry: 23, cap: 10, model: 'm'),
+      );
+      expect(learned, isNotNull);
+      expect(learned!.line, contains('cap 10'));
+    });
+
+    test('same set after compaction (renumbered labels) ⇒ no repeat', () {
+      final ux = ImageDropUx();
+      ux.observe(
+        historyDropReport(
